#!/usr/bin/env python3
import serial
import time, zlib, struct
from pd.api import command_pb2
from pd.api import response_pb2

MAGIC_NUMBER = 0x4455434B # DUCK
MAGIC_SIZE = 4

# Open the serial port (adjust device/baudrate as needed)
ser = serial.Serial('/dev/puddleduck_ctrl', timeout=2)

def send_message(message_bytes):
    """
    Send a binary protobuf message with a magic header and a CRC appended.
    
    Packet format:
      [4-byte MAGIC][4-byte total length (payload+4)][payload][4-byte CRC32]
    """
    # Compute the CRC32 over the payload (message_bytes is a bytes object)
    crc = zlib.crc32(message_bytes) & 0xffffffff
    total_len = len(message_bytes) + 4  # payload + 4-byte CRC
    # Pack magic number and total length in big-endian format.
    magic_bytes = MAGIC_NUMBER.to_bytes(4, byteorder='big')
    total_len_bytes = total_len.to_bytes(4, byteorder='big')
    crc_bytes = struct.pack(">I", crc)
    # Build the full packet.
    packet = magic_bytes + total_len_bytes + message_bytes + crc_bytes
    ser.write(packet)
    ser.flush()

def read_message():
    """
    Read a binary message with a magic header, 4-byte length prefix, and CRC check.
    Returns the payload (bytes) if CRC is valid, else None.
    """
    # First, read 4 bytes for the magic header.
    magic_bytes = ser.read(MAGIC_SIZE)
    if len(magic_bytes) < MAGIC_SIZE:
        return None
    # Validate the magic number.
    magic = int.from_bytes(magic_bytes, byteorder='big')
    if magic != MAGIC_NUMBER:
        print("Magic number mismatch. Expected 0x4455434B but got", hex(magic))
        return None

    # Read 4 bytes for total length.
    len_bytes = ser.read(4)
    if len(len_bytes) < 4:
        return None
    total_len = int.from_bytes(len_bytes, byteorder='big')
    payload_len = total_len - 4  # exclude the CRC part

    payload = ser.read(payload_len)
    if len(payload) < payload_len:
        return None

    crc_bytes = ser.read(4)
    if len(crc_bytes) < 4:
        return None
    received_crc = struct.unpack(">I", crc_bytes)[0]
    computed_crc = zlib.crc32(payload) & 0xffffffff
    if received_crc != computed_crc:
        print("CRC mismatch: received", received_crc, "computed", computed_crc)
        return None

    return payload

